addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.repeat)return;if(e.key.toLowerCase()==='e')resonate();if(e.key===' ')strike();if(e.key.toLowerCase()==='q')guard();if(e.key==='Shift'&&dashAge>1)dashAge=0;if(e.key==='Escape')togglePause()});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>{if(playing&&!paused&&!won)togglePause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing&&!paused&&!won)togglePause()});
